  "rules": [
    { "label": "api",           "priority": 50, "patterns": ["src/api/**"] },
    { "label": "tests",         "priority": 40, "patterns": ["*.test.*", "**/*.spec.*", "tests/**"] },
    { "label": "documentation", "priority": 30, "patterns": ["docs/**", "**/*.md"] },
    { "label": "ci",            "priority": 25, "patterns": [".github/**"] },
    { "label": "source",        "priority": 20, "patterns": ["src/**"] }
  ]
}

